// el juego: se aprenden en orden y los viejos se caen. Devuelve cuantos.
// out4 es uint16_t porque los indices pasan de 255.
static inline uint8_t movesAtLevel(int16_t dex, uint16_t level, uint16_t *out4) {
  if (dex < 1 || dex > DEX_COUNT) { out4[0] = MOVE_STRUGGLE; return 1; }
  uint16_t a = LEARN_OFS[dex - 1], b = LEARN_OFS[dex];
  uint8_t n = 0;
  for (uint16_t i = a; i < b; i++) {
    if (LEARN_LVL[i] > level) break;  // la lista va ordenada por nivel
    uint16_t mv = LEARN_MV[i];
    bool rep = false;
    for (uint8_t k = 0; k < n; k++) if (out4[k] == mv) rep = true;
    if (rep) continue;
    if (n < 4) out4[n++] = mv;
    else { out4[0] = out4[1]; out4[1] = out4[2]; out4[2] = out4[3]; out4[3] = mv; }
  }
  if (!n) { out4[0] = MOVE_STRUGGLE; n = 1; }  // por debajo del primer nivel
  return n;
}

// TODOS los que ya sabe, no solo los cuatro ultimos. Es la lista de la
// pantalla donde se eligen: a nivel 50 un bicho conoce 17 de media y
// hasta 31, asi que quedarse con los ultimos cuatro tira mucho a la
// basura. Devuelve cuantos ha metido, en orden de aprendizaje.
static inline uint8_t movesKnown(int16_t dex, uint16_t level,
                                 uint16_t *out, uint8_t max) {
  if (dex < 1 || dex > DEX_COUNT || !max) return 0;
  uint16_t a = LEARN_OFS[dex - 1], b = LEARN_OFS[dex];
  uint8_t n = 0;
  for (uint16_t i = a; i < b && n < max; i++) {
    if (LEARN_LVL[i] > level) break;
    uint16_t mv = LEARN_MV[i];
    bool rep = false;
    for (uint8_t k = 0; k < n; k++) if (out[k] == mv) rep = true;
    if (!rep) out[n++] = mv;
  }
  if (!n) { out[0] = MOVE_STRUGGLE; n = 1; }
  return n;
}

// PP de verdad, con los numeros de siempre.
//
// Antes esto convertia el PP a "usos por combate" (2 a 6), porque con los
// PP reales y restauracion automatica un Tackle de 35 no se agota nunca
// dentro de un combate y el numero sobra. Pero PP es un termino que todo
// el mundo entiende y que no hay que explicar en una pantalla de 466 px,
// y la tension del PP nunca estuvo en el combate suelto: esta en la
// TRAVESIA hasta el sitio donde se recupera. Aqui ese sitio es el ciclo
// de cuidado del bicho -dormir y las bayas-, asi que el PP atraviesa los
// combates y cuidar al bicho es lo que te deja seguir peleando.
static inline uint8_t movePP(uint16_t mv) {
  if (mv >= MOVE_COUNT) return 5;
  if (mv == MOVE_STRUGGLE) return 255;  // el ultimo recurso no se gasta
  uint8_t p = MOVE_TBL[mv].pp;
  return p ? p : 5;
}
